import os
import base64

# Base64 encoded entry.png
PNG_BASE64 = """"""

def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    out_path = os.path.join(out_dir, "entry.png")
    
    img_data = base64.b64decode(PNG_BASE64)
    with open(out_path, "wb") as f:
        f.write(img_data)
    
    # Read back and verify byte-for-byte
    with open(out_path, "rb") as f:
        written_data = f.read()
    
    if written_data != img_data:
        raise RuntimeError(f"Verification failed: written file at {out_path} does not match decoded image data!")
    
    print(f"Wrote {len(img_data)} bytes to {out_path} and verified successfully: written file matches decoded image data byte for byte.")

if __name__ == "__main__":
    main()
